/** Runs `work` after any in-flight update of the same order has settled. */
private async withOrderLock<T>(orderId: string, work: () => Promise<T>): Promise<T> {
  const previous = this.orderLocks.get(orderId) ?? Promise.resolve();
  const run = previous.catch(() => undefined).then(work);
  this.orderLocks.set(orderId, run);
  try {
    return await run;
  } finally {
    if (this.orderLocks.get(orderId) === run) this.orderLocks.delete(orderId);
  }
}

